defp for_type(:integer), do: %{type: "integer", description: "Integer, e.g. 1"}
defp for_type(:string),  do: %{type: "string", description: "String, e.g. 'hello'"}
defp for_type(:float),   do: %{type: "number", format: "float", description: "Float, e.g. 1.27"}
defp for_type({:parameterized, {Ecto.Enum, %{mappings: m}}}),
  do: %{type: "string", enum: Keyword.keys(m)}
